"""Write the thirteen-loop extension from measured evidence, preserving history."""
from s00_common import *
REPORT=ROOT/'report'
def save(name,text):(REPORT/name).write_text(text)
def ratio_text(r):
 if not r['cases']:return 'no matched completed comparison is available.'
 lo,hi=r['repeat_interval'];return f"the time ratio is {r['ratio']:.3f}, with repetition interval $[{lo:.3f},{hi:.3f}]$, on {r['cases']} matched requests."
def ml_interpretation(comparisons):
 statements=[]
 for control in ['native','fixed']:
  r=comparisons['learned/'+control+':all:ml']
  if not r['cases']:continue
  lo,hi=r['repeat_interval']
  if lo<=1<=hi:statements.append('The comparison with '+control+' choices does not resolve a saving beyond repetition variation.')
  elif hi<1:statements.append('The repeated timings support a saving against '+control+' choices on this fixed workload.')
  else:statements.append('The repeated timings show a cost increase against '+control+' choices on this fixed workload.')
 return ' '.join(statements)

